#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int P;
    cin >> P;

    while (P--) {
        int64 L, A, B;
        cin >> L >> A >> B;

        int64 N = B - A + 1;
        int64 M = N - 1;

        auto sumSmallest = [&](int64 t) -> i128 {
            return (i128)t * (2 * (i128)A + t - 1) / 2;
        };

        int64 lo = 0, hi = M;
        while (lo < hi) {
            int64 mid = lo + (hi - lo + 1) / 2;
            if (sumSmallest(mid) < L)
                lo = mid;
            else
                hi = mid - 1;
        }

        i128 prefix = sumSmallest(lo);
        int64 answer = (prefix + B >= L) ? lo + 1 : N;
        cout << answer << '\n';
    }

    return 0;
}
